/**
 * Returns raw inline SVG string with crisp vector path
 */
export function getGameIconSvg(iconKey, cssClass = '') {
  const body = GAME_ICON_SVGS[iconKey];
  if (!body) return '';
  return `<svg viewBox="0 0 512 512" class="gi-svg ${cssClass}" fill="currentColor" aria-hidden="true">${body}</svg>`;
}

/**
 * Resolves the appropriate Game-Icon key for a card
 */
export function getCardGameIconKey(card) {
  if (!card) return 'magnifying-glass';
  if (card.gameIcon) return card.gameIcon;
  if (card.id && MEANS_GAME_ICONS[card.id]) return MEANS_GAME_ICONS[card.id];
  if (card.id && CLUE_GAME_ICONS[card.id]) return CLUE_GAME_ICONS[card.id];
  if (card.category && CATEGORY_GAME_ICONS[card.category]) return CATEGORY_GAME_ICONS[card.category];
  return 'magnifying-glass';
}

/**
 * Renders full HTML for a card's icon (Vector Game-Icon with Emoji fallback)
 */
export function renderCardIconHtml(card, cssClass = '') {
  const key = getCardGameIconKey(card);
  const svg = getGameIconSvg(key, cssClass);
  const fallbackEmoji = card?.icon || (card?.type === 'MEANS' ? '🔪' : '🩸');
  if (svg) return svg;
  return `<span class="emoji-icon ${cssClass}">${fallbackEmoji}</span>`;
}

/**
 * Renders full HTML for a role's icon
 */
export function renderRoleIconHtml(roleId, cssClass = '') {
  const key = ROLE_GAME_ICONS[roleId] || 'sherlock-holmes';
  const svg = getGameIconSvg(key, cssClass);
  if (svg) return svg;
  return '<i class="fa-solid fa-user-secret"></i>';
}

/**
 * Renders full HTML for a scene tile's icon
 */
export function renderTileIconHtml(tileId, cssClass = '') {
  const key = SCENE_TILE_GAME_ICONS[tileId] || 'dead-head';
  const svg = getGameIconSvg(key, cssClass);
  if (svg) return svg;
  return '<i class="fa-solid fa-map-pin"></i>';
}
